import "./ProblemTable.css";

export interface ProblemRow {
  title: string;
  pattern: string;
  minutes: number;
  review: string;
  due: boolean;
}

export interface ProblemTableProps {
  rows: readonly ProblemRow[];
}

export function ProblemTable({ rows }: ProblemTableProps) {
  return (
    <div
      className="problem-table-scroll"
      role="region"
      aria-label="Solved problems"
      tabIndex={0}
    >
      <table className="problem-table">
        <caption className="problem-table__caption">Solved problems</caption>
        <thead>
          <tr>
            <th scope="col">Title</th>
            <th scope="col">Pattern</th>
            <th scope="col" className="problem-table__num">
              Minutes
            </th>
            <th scope="col">Next review</th>
          </tr>
        </thead>
        <tbody>
          {rows.length === 0 ? (
            <tr>
              <td colSpan={4} className="problem-table__empty">
                No solved problems yet.
              </td>
            </tr>
          ) : (
            rows.map((row, index) => (
              <tr
                key={`${index}-${row.title}`}
                className="problem-table__row"
                tabIndex={0}
              >
                <td>{row.title}</td>
                <td>{row.pattern}</td>
                <td className="problem-table__num">{row.minutes}</td>
                <td
                  className={
                    row.due
                      ? "problem-table__review problem-table__review--due"
                      : "problem-table__review"
                  }
                >
                  {row.due ? (
                    <>
                      <span className="problem-table__due-label">Due today</span>
                      <span className="problem-table__date"> · {row.review}</span>
                    </>
                  ) : (
                    row.review
                  )}
                </td>
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  );
}
