.problem-table td {
  padding: 0.6rem 0.75rem;
  text-align: left;
  border-bottom: 1px solid var(--myelin-border);
  vertical-align: middle;
}

.problem-table thead th {
  background: var(--myelin-surface-raised);
  color: var(--myelin-text-muted);
  font-weight: 600;
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.problem-table__num {
  text-align: right;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.problem-table__row:hover {
  background: var(--myelin-row-hover);
}

.problem-table__review {
  white-space: nowrap;
}

.problem-table__review--due {
  background: var(--myelin-due-bg);
  color: var(--myelin-due-text);
  box-shadow: inset 3px 0 0 var(--myelin-due-border);
  font-weight: 600;
}

.problem-table__due-label {
  display: inline-block;
}

.problem-table__date {
  font-weight: 400;
  opacity: 0.85;
}

.problem-table__empty {
  color: var(--myelin-text-muted);
  font-style: italic;
  text-align: center;
  padding: 1.25rem 0.75rem;
}

@media (prefers-reduced-motion: no-preference) {
  .problem-table__row {
    transition: background-color 120ms ease;
  }
}
